"""Editorial content and individual delegated review for CC-13, arts. 1829-1937."""

def r(diz, significa, exemplo, atencao, termo, explicacao):
    return {"target": None, "o_que_diz": diz, "o_que_significa": significa, "exemplo_pratico": exemplo,
            "atencao": atencao, "palavras_dificeis": [{"termo": termo, "explicacao": explicacao}]}

ROWS = {
"1829":r("A sucessão legítima segue classes sucessivas: descendentes, ascendentes, cônjuge e colaterais, com regras próprias de concorrência conjugal.","A classe anterior normalmente afasta a seguinte, e o regime de bens pode alterar a concorrência do sobrevivente com descendentes.","Falecido deixa filhos e cônjuge; antes de dividir, verificam-se bens particulares e regime matrimonial.","Por interpretação constitucional vinculante, a regra também alcança o companheiro; meação não se confunde com herança.","Vocação hereditária","ordem legal de pessoas chamadas a herdar"),
"1830":r("O Código condiciona a sucessão do cônjuge à inexistência de separação judicial ou de fato prolongada, com ressalva ligada à causa da ruptura.","A convivência e a situação jurídica ao tempo da morte influem na qualidade sucessória do sobrevivente.","Casal separado de fato antes do óbito discute se o sobrevivente conserva posição de herdeiro.","A exigência de culpa na separação de fato é constitucionalmente controvertida e demanda leitura atualizada do caso concreto.","Separação de fato","cessação da vida comum sem formalização judicial"),
"1831":r("O sobrevivente conserva direito real de morar no único imóvel residencial familiar do inventário, além da herança que lhe couber.","A proteção habitacional impede retirada imediata da moradia, independentemente do regime de bens.","Viúva permanece na única casa residencial deixada, mesmo concorrendo com filhos na herança.","O benefício exige imóvel residencial único daquela natureza no acervo e não transfere propriedade por si só.","Direito real de habitação","faculdade jurídica de residir gratuitamente em imóvel alheio"),
"1832":r("Concorrendo com descendentes, o cônjuge recebe quota igual à de quem herda por cabeça e, sendo ascendente comum, tem piso de um quarto.","A divisão igualitária ganha proteção mínima quando o sobrevivente também é ascendente dos descendentes concorrentes.","Cônjuge e três filhos comuns dividem a herança, resguardado ao sobrevivente ao menos um quarto.","O piso não se aplica automaticamente quando há descendentes exclusivos do falecido; primeiro se verifica a concorrência do art. 1.829.","Quinhão","parcela individual atribuída na herança"),
"1833":r("Descendente de grau mais próximo afasta o mais remoto, exceto quando a representação sucessória permite ocupar o lugar de outro.","Filhos precedem netos, mas netos podem representar filho pré-morto nas hipóteses legais.","Dois filhos vivos herdam; filhos de um terceiro filho falecido representam seu genitor.","Representação não é regra geral para qualquer ausência e depende dos casos previstos em lei.","Grau","distância de parentesco entre duas pessoas"),
"1834":r("Descendentes pertencentes à mesma classe sucessória recebem direitos equivalentes na herança do ascendente.","Não há diferenciação sucessória entre filhos pela origem da filiação.","Filhos biológicos e adotivos concorrem em igualdade na herança do pai.","A igualdade constitucional entre filhos impede qualificações discriminatórias.","Classe sucessória","grupo de parentes situado na mesma ordem de chamamento"),
"1835":r("Filhos dividem por pessoa; outros descendentes recebem por pessoa ou por ramo conforme estejam no mesmo grau ou representem ascendente.","A forma de partilha muda entre divisão individual e divisão pela estirpe familiar.","Netos de dois filhos pré-mortos dividem primeiro por ramos e depois dentro de cada ramo.","É necessário desenhar os graus e identificar representação antes de calcular quotas.","Estirpe","ramo familiar originado de um ascendente comum"),
"1836":r("Sem descendentes, ascendentes concorrem com o cônjuge; o grau próximo exclui o remoto e linhas paterna e materna dividem igualmente quando equivalentes.","Pais precedem avós; havendo ascendentes do mesmo grau em linhas diferentes, cada linha recebe metade.","Sem filhos, o falecido deixa mãe e avós paternos: a mãe, por ser grau mais próximo, afasta os avós.","Não há representação na linha ascendente.","Linha parental","sequência de parentes pelo lado paterno ou materno"),
"1837":r("Na concorrência com pai e mãe, o cônjuge recebe um terço; recebe metade se houver apenas um ascendente de primeiro grau ou ascendentes mais remotos.","A quota conjugal cresce quando existe um único ascendente próximo ou quando a concorrência ocorre com avós.","Falecido sem filhos deixa cônjuge e somente a mãe; cada um recebe metade.","A regra pressupõe que a concorrência sucessória do cônjuge esteja configurada.","Ascendente de primeiro grau","pai ou mãe da pessoa falecida"),
"1838":r("Na ausência de descendentes e ascendentes, o cônjuge sobrevivente recebe toda a herança.","O sobrevivente precede os parentes colaterais na ordem legal.","Pessoa sem filhos nem pais falece casada; o cônjuge herda integralmente, afastando irmãos.","É preciso satisfazer as condições sucessórias do art. 1.830 e separar eventual meação.","Sucessão integral","atribuição de todo o acervo hereditário a um sucessor"),
"1839":r("Não havendo cônjuge apto a suceder, são chamados os parentes colaterais até o quarto grau.","Irmãos, sobrinhos, tios e primos podem herdar conforme proximidade e regras específicas.","Falecido solteiro, sem descendentes ou ascendentes, deixa irmãos, que são chamados antes de primos.","Por interpretação constitucional vinculante, o companheiro recebe tratamento sucessório equivalente ao cônjuge.","Colateral","parente que não descende nem é ascendente da pessoa"),
"1840":r("Entre colaterais, o grau mais próximo exclui o remoto, salvo representação dos filhos de irmãos.","Irmãos normalmente afastam tios e primos; sobrinhos podem representar irmão pré-morto.","Irmã viva concorre com filhos de irmão falecido, que ocupam o lugar do pai.","A exceção representativa não alcança indiscriminadamente todos os colaterais.","Parente remoto","parente situado em grau mais distante"),
"1841":r("Concorrendo irmãos bilaterais e unilaterais, cada unilateral recebe metade da quota atribuída a cada bilateral.","A lei pondera o vínculo por dois genitores ou por apenas um na divisão entre irmãos.","Um irmão bilateral recebe duas unidades para cada unidade destinada a irmão unilateral.","A regra específica não autoriza discriminação fora dessa concorrência sucessória.","Irmão bilateral","irmão que compartilha ambos os genitores"),
"1842":r("Se somente irmãos unilaterais forem chamados, todos dividem a herança igualmente.","Sem irmãos bilaterais, desaparece a proporção diferenciada.","Três meio-irmãos do falecido recebem um terço cada.","A igualdade pressupõe que não existam sucessores de classe preferencial.","Irmão unilateral","irmão que compartilha apenas um genitor"),
"1843":r("Sem irmãos, sucedem os sobrinhos e, na falta deles, os tios; a divisão entre sobrinhos varia conforme a origem bilateral ou unilateral.","Sobrinhos têm preferência sobre tios e podem receber por pessoa, com ponderação do vínculo de seus pais.","Filhos de dois irmãos falecidos concorrem antes dos tios do autor da herança.","Os três parágrafos exigem identificar se os pais dos sobrinhos eram irmãos bilaterais ou unilaterais.","Sobrinho sucessível","filho de irmão chamado pela regra especial dos colaterais"),
"1844":r("Sem cônjuge, companheiro ou parente sucessível, ou havendo renúncia de todos, a herança cabe ao ente público indicado pela localização.","O patrimônio sem sucessor privado é devolvido ao Município, Distrito Federal ou União em território federal.","Após vacância e ausência de herdeiros, imóvel situado no município é transferido ao ente competente.","A devolução exige o procedimento de herança jacente e vacante; não é apropriação imediata.","Herança vacante","acervo declarado sem herdeiro privado habilitado"),
"1845":r("Descendentes, ascendentes e cônjuge são herdeiros necessários.","Essas pessoas possuem proteção sobre a legítima e limitam a liberdade testamentária.","Pai com filhos não pode destinar validamente todo o patrimônio a terceiro.","O companheiro recebe regime sucessório equivalente por interpretação constitucional, embora não conste literalmente do artigo.","Herdeiro necessário","sucessor protegido por parcela indisponível da herança"),
"1846":r("Metade da herança pertence de pleno direito aos herdeiros necessários e forma a legítima.","O testador só dispõe livremente da outra metade quando existem sucessores necessários.","Pessoa com filhos pode legar a parte disponível, preservando metade para eles.","Doações anteriores também podem repercutir no cálculo e na redução de liberalidades excessivas.","Legítima","metade reservada legalmente aos herdeiros necessários"),
"1847":r("A legítima parte dos bens existentes na abertura, menos dívidas e funeral, acrescida do valor sujeito à colação.","O cálculo reconstrói a base protegida antes de dividir a reserva entre herdeiros necessários.","Inventário deduz passivos e soma doação colacionável feita a descendente.","Meação e bens fora do acervo devem ser separados antes do cálculo sucessório.","Colação","conferência de liberalidades para igualar legítimas"),
"1848":r("Restrições de alienar, penhorar ou comunicar bens da legítima exigem justa causa declarada; conversão e alienação dependem das condições legais.","O testador não pode gravar a legítima por mero capricho, mas o juiz pode autorizar substituição do bem mantendo os ônus.","Testamento explica risco concreto e grava imóvel; venda posterior exige autorização e sub-rogação das cláusulas.","A justa causa deve constar do testamento, e o produto autorizado permanece vinculado às restrições.","Sub-rogação do ônus","transferência da restrição para o bem substituto"),
"1849":r("Herdeiro necessário beneficiado também pela parte disponível ou por legado conserva sua legítima.","Benefícios testamentários podem acumular-se com a reserva legal.","Filha recebe a legítima e ainda um legado retirado da metade disponível.","O total testamentário continua sujeito aos limites da parte disponível.","Parte disponível","fração que o testador pode destinar livremente"),
"1850":r("Para afastar colaterais, basta o testador dispor do patrimônio sem incluí-los.","Colaterais não são necessários e não exigem deserdação formal.","Pessoa sem descendentes, ascendentes ou cônjuge deixa tudo a uma instituição, afastando primos.","A disposição deve ser válida e não pode prejudicar herdeiros necessários existentes.","Exclusão tácita","afastamento resultante da destinação testamentária a outros"),
"1851":r("A representação chama determinados parentes para ocupar os direitos que caberiam ao representado se estivesse vivo.","O representante herda por ramo, preservando a posição sucessória do parente ausente.","Netos ocupam a quota de filho pré-morto do autor da herança.","Somente ocorre nas hipóteses legais e não equivale à transmissão de herança já adquirida.","Representação sucessória","chamamento legal para ocupar o lugar de outro sucessor"),
"1852":r("A representação existe na descendência, mas não na linha de ascendentes.","Netos podem representar filhos; avós não representam pais do falecido.","Pai pré-morto não é representado pelos avós quando há outro pai vivo mais próximo.","Na linha ascendente vale a preferência do grau mais próximo.","Linha reta descendente","parentesco formado por filhos, netos e demais descendentes"),
"1853":r("Na linha colateral, a representação beneficia apenas filhos de irmãos quando concorrem com irmãos do falecido.","A exceção permite que sobrinhos ocupem o ramo do irmão pré-morto.","Irmã viva concorre com sobrinhos filhos de irmão falecido.","Primos e filhos de tios não recebem representação por esta regra.","Linha transversal","parentesco colateral entre pessoas de tronco comum"),
"1854":r("Representantes recebem, em conjunto, somente o que caberia ao representado.","A quota do ramo é limitada à parcela da pessoa substituída.","Dois netos dividem a quota que pertenceria ao pai pré-morto.","Primeiro calcula-se a quota do representado; depois ela é repartida no ramo.","Quota do ramo","parcela correspondente ao representado na divisão"),
"1855":r("A parcela do representado é dividida igualmente entre seus representantes.","Integrantes do mesmo ramo partilham por cabeça a quota da estirpe.","Três filhos do representado recebem um terço da quota dele cada.","Outros graus e ramos podem exigir novo cálculo representativo.","Partilha por estirpe","divisão inicialmente feita entre ramos familiares"),
"1856":r("Quem renunciou à herança de alguém ainda pode representá-lo em outra sucessão.","A renúncia a um acervo não elimina o parentesco necessário para representar em herança diferente.","Filho renuncia à herança do pai, mas depois o representa na sucessão do avô.","São sucessões distintas; a renúncia não pode ser usada para selecionar bens dentro da mesma herança.","Autonomia das sucessões","independência jurídica entre heranças de pessoas diferentes"),
"1857":r("Pessoa capaz pode testar sobre seus bens para depois da morte, preservando a legítima, e também fazer disposições não patrimoniais.","O testamento organiza a parte disponível e pode conter vontades pessoais juridicamente admitidas.","Testador destina metade disponível a amigo e reconhece filho em disposição não patrimonial.","A legítima não pode ser invadida, e cada disposição precisa respeitar forma e licitude.","Disposição testamentária","declaração de última vontade contida no testamento"),
"1858":r("O testamento é pessoal e pode ser alterado enquanto o testador conservar capacidade.","Ninguém testa conjuntamente ou substitui o titular na formação da última vontade.","Testador revoga versão anterior e faz novo instrumento.","Personalíssimo não significa irrevogável; reconhecimento de filho, porém, segue regra própria.","Ato personalíssimo","ato que só pode ser praticado pelo próprio titular"),
"1859":r("O direito de contestar a validade do testamento extingue-se cinco anos após seu registro.","Há prazo decadencial para atacar vícios de validade do instrumento.","Interessado propõe impugnação três anos depois do registro judicial.","O termo é o registro, e questões de cumprimento de disposições podem seguir regimes diferentes.","Decadência","perda do direito de agir pelo fim do prazo legal"),
"1860":r("Não testam os legalmente incapazes nem quem não tenha pleno discernimento no ato; maiores de dezesseis anos podem testar.","A capacidade é verificada no momento da declaração, incluindo compreensão concreta da vontade.","Jovem de dezessete anos lúcido faz testamento válido observadas as formas.","Diagnóstico médico isolado não substitui a prova do discernimento no momento do ato.","Discernimento","aptidão para compreender e decidir conscientemente"),
"1861":r("Mudança posterior de capacidade não altera a validade definida no momento em que o testamento foi feito.","Testamento válido permanece válido após incapacidade; ato inválido não se convalida por recuperação posterior.","Pessoa lúcida testa e depois perde discernimento; o instrumento não se invalida por isso.","O momento relevante é a elaboração de cada testamento.","Capacidade superveniente","capacidade adquirida depois da prática do ato"),
"1862":r("As formas ordinárias são testamento público, cerrado e particular.","O testador deve escolher uma modalidade legal e cumprir suas formalidades.","Pessoa opta pelo testamento público perante tabelião e testemunhas.","Documento informal fora das modalidades pode valer apenas como codicilo em limites estreitos.","Forma ordinária","modalidade comum de testamento prevista em lei"),
"1863":r("É vedado testamento conjunto, seja simultâneo, recíproco ou condicionado entre testadores.","Cada pessoa deve manifestar sua última vontade em instrumento independente.","Cônjuges não podem assinar um único testamento deixando bens reciprocamente.","Eles podem fazer testamentos separados, desde que cada vontade seja autônoma.","Testamento conjuntivo","testamento único formado por mais de uma pessoa"),
"1864":r("O testamento público exige redação notarial, leitura perante testador e duas testemunhas e assinaturas, admitidos meios manuais ou mecânicos.","A solenidade documenta autenticidade, ciência e vontade do testador.","Tabelião redige conforme declarações, lê a todos e colhe assinaturas no mesmo ato.","A ausência de requisito essencial pode invalidar o testamento; recursos técnicos não dispensam a sequência formal.","Instrumento público","documento lavrado por agente dotado de fé pública"),
"1865":r("Se o testador não puder assinar, o tabelião registra a circunstância, assina por ele e uma testemunha também assina a seu pedido.","A impossibilidade física ou falta de alfabetização não impede testamento público, mas exige formalidade substitutiva.","Testador acamado declara vontade e tem assinatura a rogo registrada.","A razão da impossibilidade e a assinatura substitutiva devem constar do ato.","Assinatura a rogo","assinatura feita por terceiro a pedido de quem não pode assinar"),
"1866":r("Pessoa surda que saiba ler deve ler o testamento; se não souber, escolhe leitor na presença das testemunhas.","A adaptação assegura compreensão do conteúdo sem afastar a solenidade pública.","Testador surdo designa pessoa de confiança para ler o instrumento diante das testemunhas.","Devem ser registradas a condição e a forma usada para assegurar ciência.","Acessibilidade testamentária","adaptação formal que permite manifestação válida da vontade"),
"1867":r("Pessoa cega só pode usar testamento público, lido duas vezes por pessoas distintas, com registro detalhado.","A dupla leitura reduz risco de divergência entre declaração e texto escrito.","Tabelião lê o instrumento e uma testemunha escolhida repete a leitura.","A modalidade e as duas leituras são requisitos protetivos específicos.","Leitura solene","leitura formal destinada a confirmar o conteúdo do ato"),
"1868":r("O testamento cerrado exige escrito assinado, entrega e declaração perante tabelião e duas testemunhas, auto de aprovação lido e assinado.","O conteúdo permanece secreto, mas a existência e regularidade externa recebem certificação notarial.","Testador entrega envelope ao tabelião, declara sua natureza e participa da aprovação com testemunhas.","Escrita mecânica exige páginas numeradas e autenticadas pelo subscritor.","Auto de aprovação","certificação notarial das formalidades do testamento cerrado"),
"1869":r("O tabelião inicia a aprovação após o texto, certifica entrega e presença das testemunhas e fecha o instrumento; falta de espaço exige sinal e menção.","A continuidade material protege o documento contra acréscimos e substituições.","Sem espaço na folha final, tabelião põe sinal público e explica a passagem ao auto.","A cadeia física entre testamento e aprovação deve permanecer verificável.","Sinal público","marca oficial individual do tabelião"),
"1870":r("O tabelião que escreveu o testamento a pedido do testador também pode aprová-lo.","A participação na redação não o impede de realizar a certificação formal.","Tabelião redige a vontade ditada e depois lavra o auto de aprovação.","Continuam exigidas declaração livre, testemunhas e demais solenidades.","Aprovação notarial","ato que certifica externamente o testamento cerrado"),
"1871":r("O testamento cerrado pode ser escrito em português ou idioma estrangeiro, pelo testador ou por pessoa a seu pedido.","A língua estrangeira não invalida a cédula, desde que os demais requisitos sejam observados.","Testador dita texto em sua língua materna a terceiro e o assina.","O testador precisa poder ler a cédula e confirmar que ela contém sua vontade.","Cédula testamentária","documento que contém as disposições de última vontade"),
"1872":r("Quem não sabe ou não pode ler não pode fazer testamento cerrado.","O sigilo dessa forma exige que o próprio testador confira o conteúdo escrito.","Pessoa sem capacidade de leitura deve escolher modalidade pública adequada.","Assinatura isolada não supre a impossibilidade de verificar a cédula.","Inaptidão para leitura","impossibilidade de conferir pessoalmente o texto escrito"),
"1873":r("Pessoa surda e muda pode testar de forma cerrada se escrever e assinar tudo pessoalmente e declarar por escrito no invólucro que pede aprovação.","A manifestação escrita direta substitui a comunicação oral exigida na entrega.","Testador escreve integralmente a cédula e a declaração externa perante tabelião e testemunhas.","Todos os atos escritos especiais e as demais formalidades devem ser cumulativamente observados.","Declaração externa","texto no invólucro que identifica a cédula como testamento"),
"1874":r("Após aprovação e fechamento, o documento volta ao testador e o tabelião anota local e data da aprovação e entrega.","A nota no livro cria rastro oficial sem revelar o conteúdo secreto.","Tabelião registra que entregou o testamento cerrado ao titular naquele dia.","A guarda passa ao testador; perda ou destruição pode afetar o cumprimento futuro.","Nota notarial","registro resumido lançado no livro do tabelião"),
"1875":r("Depois da morte, o testamento cerrado vai ao juiz para abertura, registro e cumprimento, salvo vício externo ou suspeita de falsidade.","O controle judicial verifica a integridade formal antes de executar a vontade.","Família entrega o envelope ao juízo, que examina lacres e auto de aprovação.","O juiz não valida automaticamente conteúdo ilícito apenas porque o exterior está regular.","Abertura judicial","procedimento oficial para revelar e registrar testamento cerrado"),
"1876":r("Testamento particular pode ser manuscrito ou mecânico; cada forma exige leitura, assinatura e pelo menos três testemunhas, além de cuidados contra alterações.","A validade depende da confirmação direta da vontade e da integridade do documento.","Testador lê texto digitado sem rasuras perante três testemunhas e todos assinam.","Na forma mecânica, espaços em branco ou rasuras comprometem a segurança exigida.","Testamento particular","instrumento privado de última vontade sujeito a testemunhas"),
"1877":r("Após a morte, o testamento particular é publicado judicialmente com citação dos herdeiros legítimos.","O procedimento dá ciência aos interessados e permite controle da autenticidade.","Portador apresenta o documento e o juízo chama os herdeiros para acompanhar.","A publicação não elimina a necessidade de confirmação e exame de validade.","Publicação judicial","apresentação formal do testamento ao juízo"),
"1878":r("O testamento particular pode ser confirmado se testemunhas concordarem sobre a disposição ou leitura e reconhecerem assinaturas; falta de algumas admite prova reforçada.","A confirmação recompõe judicialmente a segurança do ato privado.","Uma testemunha sobrevivente reconhece o ato e outras provas convencem o juiz.","Com menos testemunhas, a confirmação é excepcional e depende de prova suficiente.","Testemunhas contestes","testemunhas concordantes nos pontos essenciais"),
"1879":r("Em situação excepcional declarada no documento, escrito e assinatura inteiramente pessoais podem ser confirmados mesmo sem testemunhas.","A lei admite forma extraordinária quando circunstâncias graves justificam a ausência testemunhal.","Pessoa isolada em desastre escreve, data e assina sua última vontade explicando a emergência.","A confirmação é discricionária e exige prova da excepcionalidade e autenticidade.","Testamento de emergência","testamento particular sem testemunhas por circunstância excepcional"),
"1880":r("Testamento particular pode usar língua estrangeira se as testemunhas a compreenderem.","A compreensão testemunhal assegura que elas presenciem conteúdo e declaração reais.","Testador e três testemunhas fluentes assinam texto em idioma estrangeiro.","Tradução posterior não corrige testemunhas que não entendiam o documento no ato.","Compreensão linguística","capacidade de entender o idioma da declaração"),
"1881":r("Pessoa capaz de testar pode, em escrito particular datado e assinado, dispor sobre funeral, pequenas esmolas e objetos pessoais de baixo valor.","O codicilo simplifica vontades patrimoniais modestas e providências pessoais.","Autor destina relógio de uso pessoal e pequena doação beneficente em escrito assinado.","Não serve para distribuir patrimônio relevante nem invadir a legítima.","Codicilo","escrito simplificado para disposições de pequena importância"),
"1882":r("As disposições simplificadas valem como codicilo, exista ou não testamento, preservados direitos de terceiros.","O codicilo é autônomo, mas não pode prejudicar direitos já protegidos.","Pessoa deixa apenas codicilo sobre funeral sem elaborar testamento.","Conflitos com testamento posterior e direitos alheios exigem compatibilização.","Direito de terceiro","posição jurídica de pessoa estranha ao ato que deve ser preservada"),
"1883":r("Codicilo também pode nomear ou substituir testamenteiro.","A função de executar a última vontade pode ser atribuída pelo escrito simplificado.","Autor indica pessoa de confiança para cumprir disposições funerárias.","A nomeação não amplia o conteúdo patrimonial permitido ao codicilo.","Testamenteiro","pessoa encarregada de executar o testamento"),
"1884":r("Codicilo é revogado por outro equivalente e também por testamento posterior que não o confirme ou modifique.","A vontade posterior incompatível ou silenciosa pode retirar eficácia do escrito anterior.","Novo testamento deixa de confirmar codicilo antigo, que perde efeito.","Deve-se comparar datas e conteúdo para saber se houve confirmação, alteração ou revogação.","Revogação tácita","perda de eficácia deduzida de ato posterior incompatível"),
"1885":r("Codicilo fechado segue o procedimento de abertura do testamento cerrado.","O invólucro protegido exige controle judicial antes da execução.","Após o falecimento, envelope com codicilo é apresentado ao juiz para abertura.","A forma de abertura não transforma codicilo em testamento nem amplia seus limites.","Documento cerrado","escrito mantido fechado até abertura formal"),
"1886":r("Os testamentos especiais admitidos são marítimo, aeronáutico e militar.","Essas formas respondem a situações extraordinárias de viagem ou serviço militar.","Passageiro em navio nacional utiliza testamento marítimo nas condições legais.","Cada modalidade possui pressupostos e caducidade próprios.","Testamento especial","forma excepcional de testar prevista para situação específica"),
"1887":r("Não existem outras modalidades especiais além das três previstas no Código.","Situação incomum não autoriza criar forma testamentária nova por analogia.","Viajante terrestre não inventa testamento especial fora das formas legais.","Ainda podem existir testamento particular emergencial e formas ordinárias, se seus requisitos forem cumpridos.","Tipicidade testamentária","exigência de usar uma forma prevista em lei"),
"1888":r("Em navio nacional durante viagem, pessoa pode testar perante comandante e duas testemunhas, imitando forma pública ou cerrada, com registro no diário de bordo.","A autoridade naval substitui o tabelião enquanto a situação de viagem impede a forma comum.","Passageiro em alto-mar declara vontade ao comandante diante de duas testemunhas.","Navio estrangeiro e permanência em porto com acesso à forma ordinária não satisfazem automaticamente a regra.","Diário de bordo","registro oficial dos acontecimentos da embarcação"),
"1889":r("Em aeronave militar ou comercial durante viagem, testa-se perante pessoa indicada pelo comandante, seguindo as garantias do testamento marítimo.","A designação formal cria responsável pelo ato excepcional a bordo.","Passageiro entrega última vontade à pessoa indicada, diante das testemunhas exigidas.","A viagem e as formalidades do artigo anterior devem coexistir.","Pessoa designada","responsável escolhido pelo comandante para receber o ato"),
"1890":r("O comandante guarda o testamento marítimo ou aeronáutico e o entrega à autoridade no primeiro porto ou aeroporto nacional, com recibo registrado.","A cadeia de custódia protege o documento até sua entrega oficial.","Ao pousar no Brasil, comandante entrega o testamento e anota o recibo no diário.","Falha de custódia pode gerar prova e responsabilidade, sem dispensar exame judicial do ato.","Cadeia de custódia","sequência documentada de guarda e entrega"),
"1891":r("O testamento de bordo caduca se o testador sobreviver à viagem e aos noventa dias após desembarcar onde poderia testar normalmente.","A forma excepcional perde razão após período seguro para substituição por testamento ordinário.","Viajante retorna e vive quatro meses com acesso a tabelião; o testamento marítimo caduca.","O prazo depende de efetiva possibilidade de testar em terra.","Caducidade","perda de eficácia por evento posterior previsto em lei"),
"1892":r("Testamento marítimo não vale se o navio estava em porto onde era possível desembarcar e testar pela forma ordinária.","A modalidade especial só existe diante de real impossibilidade prática da forma comum.","Passageiro em porto com livre desembarque não pode preferir a forma marítima por conveniência.","A disponibilidade concreta de desembarque e testamento ordinário deve ser provada.","Subsidiariedade da forma","uso excepcional apenas quando a forma comum não está disponível"),
"1893":r("Militares e pessoas a serviço das Forças Armadas em campanha ou isolamento podem testar sem tabelião perante testemunhas e autoridades indicadas.","A forma militar adapta redação e testemunho às condições de guerra, destacamento ou hospital.","Militar em unidade isolada dita vontade ao comandante diante das testemunhas exigidas.","Número de testemunhas, assinatura substitutiva e autoridade competente variam conforme a situação descrita.","Praça sitiada","local militar cercado e com comunicação restringida"),
"1894":r("Quem puder escrever faz testamento militar de próprio punho, datado e assinado, apresentando-o a autoridade militar perante duas testemunhas, com nota circunstanciada.","A apresentação certifica tempo, lugar e autenticidade do escrito pessoal.","Soldado entrega cédula aberta ao oficial, que anota data e assina com testemunhas.","A nota da autoridade e assinaturas testemunhais integram a solenidade.","Auditor militar","autoridade jurídica militar que recebe o testamento"),
"1895":r("O testamento militar caduca após noventa dias contínuos em local onde seja possível testar ordinariamente, salvo forma com solenidades reforçadas.","A excepcionalidade cessa com estabilidade suficiente, mas a modalidade mais formal indicada pode subsistir.","Militar regressa e permanece mais de noventa dias em cidade com tabelião.","A contagem exige possibilidade contínua de usar forma ordinária.","Solenidade reforçada","formalidade adicional que preserva o ato excepcional"),
"1896":r("Em combate ou após ferimento, pessoas abrangidas podem declarar oralmente a última vontade a duas testemunhas; o ato perde efeito se sobreviverem à guerra ou se recuperarem.","O testamento nuncupativo é extrema exceção ligada a risco imediato de morte.","Combatente gravemente ferido declara vontade a dois colegas e falece em razão do ferimento.","Sobrevivência à guerra ou convalescença elimina a eficácia dessa declaração oral.","Testamento nuncupativo","última vontade oral admitida em combate"),
"1897":r("Herdeiro ou legatário pode ser nomeado sem condição, sob condição, com encargo ou por motivo declarado.","O testador pode modular o benefício dentro dos limites de licitude e possibilidade.","Legado é deixado a instituição com encargo de manter projeto cultural.","Condição ilícita, impossível ou captatória pode invalidar ou ser desconsiderada conforme o caso.","Modo ou encargo","obrigação imposta ao beneficiário de liberalidade"),
"1898":r("Termo que fixe início ou fim do direito do herdeiro é ignorado, salvo no fideicomisso.","A instituição hereditária não pode ficar temporalmente fracionada fora da exceção legal.","Cláusula dizendo que herdeiro só será titular a partir de data futura é tida por não escrita.","Condições válidas e legados seguem regras próprias; a exceção fideicomissária é restrita.","Termo testamentário","evento futuro e certo que delimita efeitos no tempo"),
"1899":r("Entre interpretações possíveis, deve prevalecer a que melhor realize a vontade do testador.","O intérprete procura sentido juridicamente válido e fiel ao conjunto do testamento.","Expressão ambígua é lida em conjunto com outras cláusulas para identificar o beneficiário pretendido.","A busca da intenção não permite criar vontade sem apoio no instrumento e nas provas admitidas.","Interpretação testamentária","determinação do sentido da última vontade"),
"1900":r("São nulas disposições captatórias, destinadas a pessoa impossível de identificar, delegações indevidas de beneficiário ou valor e benefícios a pessoas legalmente impedidas.","A lei exige autonomia do testador e determinação suficiente do favorecido e do objeto.","Cláusula promete herança se beneficiário também testar em favor do autor; ela é nula.","Cada inciso contém vício próprio; a nulidade da cláusula não elimina automaticamente todo o testamento.","Condição captatória","condição que procura obter benefício em outro testamento"),
"1901":r("É válida a escolha por terceiro entre pessoas ou grupos delimitados e a remuneração por serviços finais mesmo com valor definido por outra pessoa.","A lei admite delegação limitada quando o testador fixa universo objetivo ou causa remuneratória.","Testador deixa benefício a um entre três sobrinhos, a ser escolhido por pessoa indicada.","O terceiro não recebe liberdade irrestrita para inventar beneficiário fora dos limites dados.","Determinação por terceiro","escolha complementar feita dentro de parâmetros testamentários"),
"1902":r("Benefício geral a pobres ou instituições assistenciais refere-se, em regra, ao domicílio do testador, com preferência das entidades privadas locais.","A lei supre a falta de localização específica da disposição beneficente.","Testador deixa quantia aos pobres sem indicar cidade; considera-se seu domicílio ao falecer.","Manifestação clara em favor de outra localidade prevalece sobre a regra supletiva.","Disposição beneficente","liberalidade destinada a finalidade de assistência"),
"1903":r("Erro no nome do beneficiário ou da coisa invalida a disposição, salvo identificação segura pelo contexto, documentos ou fatos inequívocos.","O erro formal pode ser superado se a vontade real for objetivamente demonstrável.","Testamento erra uma letra do nome, mas outros dados identificam sem dúvida a sobrinha.","A correção interpretativa exige certeza; não autoriza escolher entre candidatos plausíveis.","Erro de designação","indicação incorreta de pessoa ou objeto"),
"1904":r("Se vários herdeiros são nomeados sem quotas, a parte disponível é dividida igualmente entre eles.","O silêncio sobre proporções gera igualdade no benefício testamentário.","Três amigos instituídos sem percentuais recebem um terço da parte disponível cada.","A igualdade alcança a porção testamentável, preservada a legítima.","Quota testamentária","fração atribuída ao herdeiro instituído"),
"1905":r("Nomeações individuais e coletivas geram uma quota para cada pessoa indicada e uma para cada grupo designado.","O grupo é tratado como unidade na primeira divisão, repartindo internamente sua quota.","Testador nomeia Ana, Bruno e os filhos de Carla; formam-se três quotas iniciais.","A redação concreta pode revelar intenção diferente e deve ser interpretada como conjunto.","Designação coletiva","nomeação de beneficiários como um grupo"),
"1906":r("Quotas testamentárias que não consumam toda a herança deixam o saldo aos herdeiros legítimos.","A sucessão legítima completa a parte não alcançada pela vontade.","Testador distribui 30% e silencia sobre o restante; o saldo segue a ordem legal.","Antes se preserva a legítima e se verifica se os percentuais incidem sobre todo o acervo ou parte disponível.","Remanescente","parte da herança não abrangida pelas quotas fixadas"),
"1907":r("Quando algumas quotas são fixadas e outras não, os herdeiros sem percentual dividem igualmente o saldo depois das parcelas determinadas.","A lei combina respeito às quotas expressas com igualdade entre as indeterminadas.","Um herdeiro recebe 40%; dois outros dividem os 60% restantes.","O cálculo continua limitado pela legítima e por eventual redução testamentária.","Quinhão indeterminado","parcela sem percentual definido pelo testador"),
"1908":r("Objeto expressamente excluído do quinhão do herdeiro instituído cabe aos herdeiros legítimos.","A exclusão específica não aumenta automaticamente as quotas dos demais testamentários.","Testador nomeia herdeiro, mas exclui determinado imóvel, que segue à sucessão legítima.","É necessário distinguir exclusão de objeto, legado e simples regra de partilha.","Exclusão objetiva","retirada de bem específico da instituição testamentária"),
"1909":r("Disposição contaminada por erro, dolo ou coação é anulável em quatro anos desde a ciência do vício.","Vontade testamentária defeituosa pode ser desconstituída dentro do prazo legal.","Interessado descobre que beneficiário coagiu o testador e propõe ação no prazo.","O prazo nasce do conhecimento do vício, que precisa ser provado; anulabilidade difere de nulidade.","Coação testamentária","pressão grave que compromete a liberdade de testar"),
"1910":r("A ineficácia de uma cláusula alcança outras que dependiam dela para serem determinadas.","Disposições conexas caem quando a primeira era pressuposto essencial das demais.","Legado acessório perde sentido após ineficácia da instituição principal da qual dependia.","Cláusulas independentes devem ser preservadas sempre que possível.","Dependência testamentária","vínculo lógico que torna uma disposição pressuposto de outra"),
"1911":r("Inalienabilidade imposta por liberalidade também gera impenhorabilidade e incomunicabilidade; substituição autorizada transfere as restrições ao novo bem.","As três proteções acompanham o patrimônio clausulado, inclusive após alienação judicialmente permitida.","Herdeiro obtém autorização para vender imóvel gravado e compra outro sujeito aos mesmos ônus.","Alienação por conveniência econômica exige autorização judicial e sub-rogação; a legítima ainda observa o art. 1.848.","Incomunicabilidade","restrição que impede ingresso do bem no patrimônio comum do casal"),
"1912":r("Legado de bem específico alheio ao testador na abertura da sucessão é ineficaz.","O testador não transmite coisa determinada que não integra seu patrimônio ao morrer.","Automóvel vendido antes do óbito não pode ser entregue ao legatário.","Legados de gênero e a obrigação imposta a herdeiro sobre coisa própria seguem regras diferentes.","Legado de coisa certa","atribuição testamentária de bem individualizado"),
"1913":r("Se testamento obriga herdeiro ou legatário a entregar coisa própria a terceiro, recusa equivale à renúncia do benefício recebido.","O beneficiário escolhe entre cumprir o encargo patrimonial ou perder herança ou legado.","Herdeiro recebe quota condicionada à entrega de obra própria e se recusa, sendo tratado como renunciante.","A coisa deve pertencer ao onerado e a disposição precisa ser válida e suficientemente determinada.","Legado de coisa alheia","legado cujo cumprimento recai sobre bem de outro beneficiário"),
"1914":r("Se a coisa pertence apenas parcialmente ao testador ou ao beneficiário onerado, o legado vale somente nessa proporção.","A eficácia acompanha a titularidade efetivamente disponível.","Testador possui metade de imóvel legado; o legatário recebe apenas essa metade.","A outra fração não é adquirida automaticamente nem substituída por dinheiro.","Titularidade parcial","propriedade de apenas uma fração do bem"),
"1915":r("Legado definido pelo gênero deve ser cumprido mesmo que não exista exemplar no acervo.","A obrigação é fornecer coisa da espécie indicada, não necessariamente bem já pertencente ao testador.","Testamento lega um computador sem individualizá-lo; herdeiro adquire um para cumprir.","Qualidade e escolha seguem os arts. 1.929 a 1.931 e a intenção testamentária.","Coisa genérica","bem definido por espécie, quantidade ou qualidade, sem individualização"),
"1916":r("Bem próprio individualizado só é legado se estiver na herança ao morrer; quantidade inferior limita o legado ao existente.","Alienação ou redução do estoque antes do óbito produz ineficácia total ou parcial.","Testador lega cem garrafas específicas, mas deixa quarenta; apenas quarenta são entregues.","É necessário distinguir coisa singularizada de legado puramente genérico.","Adempção","ineficácia do legado porque a coisa deixou o patrimônio"),
"1917":r("Bem destinado a estar em lugar indicado só é legado se ali for encontrado, salvo remoção temporária.","A localização integra a individualização feita pelo testador.","Quadro legado como existente no escritório estava temporariamente em restauração e continua abrangido.","Remoção definitiva pode indicar que o objeto não corresponde mais à disposição.","Remoção transitória","deslocamento temporário sem mudança definitiva de destinação"),
"1918":r("Legado de crédito ou perdão de dívida vale pelo saldo existente ao morrer e se cumpre com entrega do título, sem incluir dívidas posteriores ao testamento.","A liberalidade acompanha a relação obrigacional existente, limitada ao valor efetivo final.","Testador perdoa dívida que estava parcialmente paga; somente o saldo remanescente é quitado.","Novas dívidas do mesmo devedor não são incluídas sem declaração expressa.","Legado de quitação","perdão testamentário de dívida do beneficiário"),
"1919":r("Legado feito ao credor não compensa dívida do testador sem declaração expressa; pagamento posterior da dívida preserva o legado.","Crédito e liberalidade são benefícios distintos salvo vontade clara de compensar.","Devedor lega quantia ao credor e quita a dívida antes de morrer; o legado continua devido.","A intenção compensatória não se presume.","Compensação testamentária","uso do legado para satisfazer dívida existente"),
"1920":r("Legado de alimentos cobre sustento, saúde, vestuário, moradia e educação do menor enquanto viver.","A expressão recebe conteúdo amplo de manutenção pessoal, ajustado às necessidades e ao testamento.","Beneficiário menor recebe custeio de casa, escola e tratamento médico.","Valor e modo de cumprimento dependem do acervo, da intenção e das necessidades concretas.","Legado de alimentos","prestação testamentária destinada à manutenção vital"),
"1921":r("Usufruto legado sem duração expressa é vitalício para o legatário.","O beneficiário usa e frui o bem durante a vida, sem adquirir a nua-propriedade.","Testador deixa usufruto de imóvel sem prazo; extingue-se com a morte do legatário.","A regra não cria usufruto sucessivo além da vida do beneficiário.","Usufruto vitalício","direito de usar e obter frutos enquanto viver o titular"),
"1922":r("Aquisições acrescentadas depois a imóvel legado não entram automaticamente, mas benfeitorias feitas no próprio prédio acompanham o legado.","A ampliação patrimonial por compra difere da melhoria física do bem individualizado.","Testador compra lote vizinho após legar casa; o lote não entra, mas reforma necessária da casa entra.","Declaração expressa pode abranger aquisições contíguas.","Benfeitoria voluptuária","melhoria de recreio ou embelezamento sem necessidade funcional"),
"1923":r("Com a morte, coisa certa do acervo pertence ao legatário, mas a posse não é imediata; frutos acompanham o bem salvo condição ou termo.","O direito nasce na abertura, enquanto a entrega deve ocorrer pelo procedimento sucessório.","Legatário de imóvel recebe frutos desde o óbito, mas não invade a posse por conta própria.","Condição suspensiva e termo inicial alteram aquisição de frutos e exigibilidade.","Saisine do legado","aquisição do direito ao legado na abertura da sucessão"),
"1924":r("Não se exige legado enquanto houver litígio sobre validade do testamento ou enquanto condição ou prazo estiver pendente.","A exigibilidade aguarda certeza sobre o título e ocorrência do evento previsto.","Legatário espera decisão final sobre validade antes de cobrar entrega.","Suspensão do pedido não significa necessariamente perda do direito.","Exigibilidade","momento em que a prestação pode ser cobrada"),
"1925":r("Legado em dinheiro rende juros somente após mora de quem deve pagá-lo.","O atraso juridicamente caracterizado inicia a remuneração pelo não pagamento.","Herdeiro é constituído em mora e passa a dever juros sobre a quantia legada.","Abertura da sucessão, por si só, não inicia os juros deste legado.","Mora","atraso juridicamente relevante no cumprimento"),
"1926":r("Renda vitalícia ou pensão periódica legada começa a correr desde a morte do testador.","O direito periódico nasce com a abertura da sucessão.","Beneficiário de pensão mensal conta a primeira competência a partir do óbito.","Pagamento e vencimento de cada parcela podem seguir periodicidade própria.","Renda vitalícia","prestação periódica devida durante a vida do beneficiário"),
"1927":r("Em prestações periódicas certas, o primeiro período começa na morte e cada parcela é adquirida ao iniciar o respectivo período.","O legatário mantém a parcela do período iniciado mesmo que morra antes do final.","Beneficiário inicia trimestre e falece depois; a prestação daquele trimestre integra seu patrimônio.","A regra trata aquisição da parcela, não necessariamente sua data de cobrança.","Período aquisitivo","intervalo cujo início gera direito à prestação"),
"1928":r("Prestação periódica é exigível ao fim de cada período; alimentos são pagos no começo, salvo vontade diferente.","A necessidade alimentar justifica adiantamento em relação às demais prestações.","Pensão alimentar mensal é paga no primeiro dia, enquanto outra renda vence ao final.","O testamento pode estabelecer calendário distinto dentro dos limites válidos.","Pagamento antecipado","cumprimento no início do período de referência"),
"1929":r("Na coisa genérica, o herdeiro escolhe exemplar de qualidade intermediária.","A escolha não pode impor ao legatário o pior nem exigir o melhor item do gênero.","Entre veículos da mesma categoria, herdeiro seleciona um de condição média.","Características determinadas no testamento prevalecem sobre o padrão supletivo.","Qualidade média","padrão intermediário entre melhor e pior exemplar"),
"1930":r("Terceiro encarregado da escolha também observa qualidade média; recusando ou não podendo escolher, o juiz o faz.","A escolha não fracassa pela omissão do terceiro indicado.","Especialista nomeado não aceita a tarefa e o juiz seleciona o bem adequado.","O controle judicial permanece vinculado ao gênero e ao critério de equilíbrio.","Escolha judicial","determinação do objeto pelo juiz em substituição ao terceiro"),
"1931":r("Se a escolha couber ao legatário, ele pode selecionar o melhor exemplar existente; inexistindo no acervo, o herdeiro fornece congênere de qualidade média.","A vantagem de escolher o melhor limita-se ao patrimônio deixado.","Legatário escolhe o melhor cavalo do acervo; sem cavalos, recebe exemplar médio adquirido pelo herdeiro.","A opção não autoriza escolher coisa fora do gênero definido.","Congênere","coisa pertencente ao mesmo gênero ou categoria"),
"1932":r("No legado com duas prestações alternativas, presume-se que o herdeiro escolhe.","O responsável pelo cumprimento define qual alternativa entregar, salvo cláusula contrária.","Testamento lega carro ou quantia equivalente; herdeiro faz a escolha.","A escolha deve respeitar boa-fé e a exata alternativa prevista.","Legado alternativo","legado cumprível por uma entre duas ou mais prestações"),
"1933":r("Morrendo antes de escolher quem tinha a opção, o poder passa aos herdeiros dessa pessoa.","A faculdade de individualizar o legado integra a posição transmissível do optante.","Herdeiro encarregado falece antes da escolha; seus sucessores a exercem.","A transmissão pressupõe que a opção ainda não tenha sido validamente exercida.","Poder de escolha","faculdade jurídica de determinar a prestação entre alternativas"),
"1934":r("Sem cláusula específica, herdeiros cumprem legados e, na falta deles, legatários, proporcionalmente ao que recebem; indicação do testador distribui o encargo.","O custo dos legados acompanha o benefício sucessório, salvo atribuição testamentária distinta.","Dois herdeiros que recebem 60% e 40% suportam o legado na mesma proporção.","O onerado indicado responde conforme o testamento, e múltiplos onerados rateiam pelo benefício recebido.","Onerado","beneficiário incumbido de cumprir um legado ou encargo"),
"1935":r("Quando o legado recai sobre coisa do próprio herdeiro ou legatário, somente ele a entrega, com regresso proporcional contra coerdeiros, salvo ordem contrária.","O titular suporta a execução imediata, mas pode repartir internamente o peso do legado.","Herdeiro entrega bem próprio ao legatário e cobra dos coerdeiros suas quotas do ônus.","O testador pode afastar expressamente o direito de regresso.","Direito de regresso","faculdade de recuperar de outros a parte do encargo que lhes cabe"),
"1936":r("Custos e riscos da entrega do legado cabem ao legatário, salvo disposição testamentária diferente.","A regra supletiva transfere ao beneficiário despesas de transporte e risco ligado à entrega.","Legatário paga frete para receber objeto situado em outra cidade.","Danos decorrentes de culpa do responsável não são automaticamente transferidos por essa regra.","Risco da entrega","responsabilidade por eventos ocorridos na transferência do bem"),
"1937":r("A coisa legada é entregue com acessórios, no lugar e estado do óbito, e conserva os encargos existentes.","O legatário recebe o bem tal como integra o acervo, com elementos acessórios e ônus reais.","Imóvel hipotecado é entregue com suas instalações e com a garantia registrada.","Deterioração culposa após o óbito e dívidas pessoais exigem análise própria.","Acessório","bem ou elemento ligado funcionalmente à coisa principal"),
}

# B marks records whose final version reflects a substantive refinement after individual review.
_B = {"1829","1830","1831","1832","1835","1836","1837","1843","1844","1845","1847","1848",
      "1851","1853","1857","1859","1860","1864","1866","1867","1868","1869","1873","1875","1876",
      "1878","1879","1881","1884","1888","1889","1891","1893","1894","1895","1896","1897","1898",
      "1900","1901","1902","1903","1905","1906","1907","1909","1910","1911","1913","1916","1918",
      "1920","1922","1923","1924","1927","1928","1929","1930","1931","1934","1935","1937"}
AUDIT = {article: {"classification": "B" if article in _B else "A",
                   "rationale": "Revisão individual confirmou o núcleo jurídico e delimitou o risco: " + row["atencao"]}
         for article, row in ROWS.items()}
